<style>
:root{--ink:oklch(0.17 0.012 78);--ink-2:oklch(0.22 0.014 78);--ink-3:oklch(0.28 0.014 78);--line:oklch(0.35 0.016 78);--gold:oklch(0.80 0.155 78);--gold-soft:oklch(0.86 0.12 82);--light:oklch(0.97 0.004 78);--muted:oklch(0.79 0.008 78);font-family:'Instrument Sans',ui-sans-serif,system-ui;color:var(--light);background:var(--ink)}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 50% -20%,oklch(0.80 0.155 78/.11),transparent 42%),var(--ink);-webkit-font-smoothing:antialiased}.wrap{max-width:960px;margin:0 auto;padding:38px 20px 56px}.brand{display:flex;align-items:center;height:42px}.brand img{width:132px;height:auto;display:block}.card{background:var(--ink-2);border:1px solid var(--line);border-radius:22px;box-shadow:0 30px 70px oklch(0 0 0/.38);padding:clamp(24px,4vw,42px);margin-top:28px}.steps{display:flex;gap:7px;margin:28px 0 34px}.step{height:5px;background:var(--ink-3);flex:1;border-radius:99px;transition:background .2s ease}.step.on{background:var(--gold)}h1,h2{margin:0;letter-spacing:-.025em;text-wrap:balance}h1{font-size:2rem;line-height:1.12;margin-bottom:8px}h2{font-size:1.2rem;line-height:1.3;margin-bottom:20px}p,.hint{color:var(--muted);line-height:1.6;max-width:68ch}.grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}.full{grid-column:1/-1}label{font-size:.84rem;font-weight:600;display:block;margin-bottom:7px;color:var(--light)}input,select{width:100%;min-height:48px;padding:11px 13px;border:1px solid var(--line);border-radius:11px;font:500 .96rem/1.2 'Instrument Sans',sans-serif;color:var(--light);background:var(--ink)}input::placeholder{color:oklch(0.67 0.008 78)}input:hover,select:hover{border-color:oklch(0.48 0.02 78)}input:focus,select:focus{outline:3px solid oklch(0.80 0.155 78/.2);outline-offset:1px;border-color:var(--gold)}select{color-scheme:dark}.actions{display:flex;justify-content:space-between;gap:12px;margin-top:30px;padding-top:24px;border-top:1px solid var(--line)}button{min-height:48px;border:0;border-radius:999px;padding:0 21px;font:600 .96rem/1 'Instrument Sans',sans-serif;cursor:pointer;transition:background .18s ease,transform .18s ease,box-shadow .18s ease}button:hover{box-shadow:0 10px 24px oklch(0 0 0/.25)}button:active{transform:translateY(1px)}button:focus-visible{outline:3px solid var(--gold-soft);outline-offset:3px}.primary{background:var(--gold);color:oklch(0.20 0.02 78)}.primary:hover{background:var(--gold-soft)}.secondary{background:transparent;color:var(--light);border:1px solid var(--line)}.secondary:hover{background:oklch(1 0 0/.06)}.danger{color:oklch(0.78 0.16 27);background:oklch(0.32 0.08 27/.35);border:1px solid oklch(0.58 0.16 27/.35)}.page{display:none}.page.active{display:block}.client{border:1px solid var(--line);background:var(--ink);border-radius:14px;padding:18px;margin:13px 0}.status{padding:48px 20px;text-align:center}.status h1{color:var(--gold)}.status p{margin-inline:auto}.error{background:oklch(0.30 0.08 27/.42);border:1px solid oklch(0.58 0.16 27/.42);color:oklch(0.87 0.08 27);padding:13px 15px;border-radius:11px;margin:16px 0}.busy{min-height:18px;font-size:.78rem;color:var(--gold-soft);margin-top:6px}@media(max-width:650px){.wrap{padding:22px 14px 36px}.brand{height:36px}.brand img{width:112px}.grid{grid-template-columns:1fr}.full{grid-column:auto}.card{padding:22px 18px;border-radius:17px;margin-top:20px}h1{font-size:1.65rem}.actions{position:sticky;bottom:0;background:var(--ink-2);margin-inline:-18px;padding:16px 18px;border-top:1px solid var(--line)}button{flex:1}}@media(prefers-reduced-motion:reduce){button,.step{transition:none}}
</style></head><body><div class="wrap"><div class="brand"><img src="https://www.virtus.chat/img/virtus-lockup-claro-480.png" alt="Virtus Chat" width="480" height="209"></div><div class="card">
