<form method="post" action="{{ route('onboarding.submit',$token) }}" id="wizard">@csrf
<section class="page active"><h2>1. Identificação</h2><div class="grid"><div class="full"><label>CNPJ</label><input name="company[document]" id="cnpj" value="{{ old('company.document',data_get($onboarding->payload,'company.document')) }}" required placeholder="00.000.000/0000-00"><div id="cnpj-status" class="busy"></div></div><div><label>Razão social</label><input name="company[legal_name]" id="legal_name" required></div><div><label>Nome fantasia</label><input name="company[trade_name]" id="trade_name"></div><div><label>E-mail da empresa</label><input type="email" name="company[email]" id="email" required></div><div><label>Telefone</label><input name="company[phone]" id="phone" required></div></div></section>
<section class="page"><h2>2. Endereço</h2><div class="grid"><div><label>CEP</label><input name="company[cep]" id="cep" required><div id="cep-status" class="busy"></div></div><div><label>Logradouro</label><input name="company[street]" id="street" required></div><div><label>Número</label><input name="company[number]" required></div><div><label>Complemento</label><input name="company[complement]"></div><div><label>Bairro</label><input name="company[district]" id="district" required></div><div><label>Cidade</label><input name="company[city]" id="city" required></div><div><label>UF</label><input name="company[state]" id="state" maxlength="2" required></div></div></section>
<section class="page"><h2>3. Perfil e acessos</h2><div class="grid"><div class="full"><label>Como sua empresa será atendida?</label><select name="company_type" id="type"><option value="direct">Cliente direto</option><option value="partner">Parceiro que gerencia clientes finais</option></select></div></div><h2>Administradores</h2><p class="hint">Cliente direto: 1 acesso. Parceiro: até 3 acessos.</p><div id="admins"></div><button type="button" class="secondary" id="add-admin">+ Adicionar administrador</button></section>
<section class="page"><h2>4. Clientes do parceiro</h2><div id="partner-help"><p class="hint">Adicione os clientes finais que também devem receber portal e acesso.</p><div id="clients"></div><button type="button" class="secondary" id="add-client">+ Adicionar cliente</button></div><div id="direct-help"><p>Confira os dados e envie. Nada será criado antes da aprovação do super administrador.</p></div></section>
<div class="actions"><button type="button" class="secondary" id="back" hidden>Voltar</button><button type="button" class="primary" id="next">Continuar</button><button type="submit" class="primary" id="submit" hidden>Enviar para aprovação</button></div></form>
@endif</div></div>
@if(!in_array($onboarding->status,['submitted','approved']))<script>
const csrf=document.querySelector('[name=_token]').value,pages=[...document.querySelectorAll('.page')],steps=[...document.querySelectorAll('.step')];let current=0,adminCount=0,clientCount=0;
const val=(id,v)=>{if(v!==null&&v!==undefined&&v!=='')document.getElementById(id).value=v};
async function lookup(path,body,status){status.textContent='Consultando…';try{let r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify(body)}),j=await r.json();if(!j.ok)throw Error(j.erro);status.textContent='Dados encontrados e preenchidos.';return j.dados}catch(e){status.textContent=e.message||'Não foi possível consultar.';return null}}
document.getElementById('cnpj').addEventListener('blur',async e=>{if(e.target.value.replace(/\D/g,'').length!==14)return;let d=await lookup('{{ route('onboarding.cnpj',$token) }}',{cnpj:e.target.value},document.getElementById('cnpj-status'));if(d){val('legal_name',d.razao_social);val('trade_name',d.nome_fantasia);val('email',d.email);val('phone',d.telefone);val('cep',d.cep);val('street',d.logradouro);val('district',d.bairro);val('city',d.cidade);val('state',d.uf)}});
document.getElementById('cep').addEventListener('blur',async e=>{if(e.target.value.replace(/\D/g,'').length!==8)return;let d=await lookup('{{ route('onboarding.cep',$token) }}',{cep:e.target.value},document.getElementById('cep-status'));if(d){val('street',d.logradouro);val('district',d.bairro);val('city',d.cidade);val('state',d.uf)}});
function addAdmin(){if(adminCount>=3)return;let i=adminCount++;document.getElementById('admins').insertAdjacentHTML('beforeend',`<div class="client grid"><div><label>Nome</label><input name="admins[${i}][name]" required></div><div><label>E-mail</label><input type="email" name="admins[${i}][email]" required></div></div>`)}
function addClient(){let i=clientCount++;document.getElementById('clients').insertAdjacentHTML('beforeend',`<div class="client grid"><div><label>CNPJ</label><input name="clients[${i}][document]" required></div><div><label>Razão social</label><input name="clients[${i}][legal_name]" required></div><div><label>Nome fantasia</label><input name="clients[${i}][trade_name]"></div><div><label>E-mail da empresa</label><input type="email" name="clients[${i}][email]" required></div><div><label>Telefone</label><input name="clients[${i}][phone]"></div><div><label>Nome do responsável</label><input name="clients[${i}][admin][name]" required></div><div><label>E-mail para acesso</label><input type="email" name="clients[${i}][admin][email]" required></div><div><button type="button" class="danger" onclick="this.closest('.client').remove()">Remover</button></div></div>`)}
addAdmin();document.getElementById('add-admin').onclick=addAdmin;document.getElementById('add-client').onclick=addClient;
function render(){pages.forEach((p,i)=>p.classList.toggle('active',i===current));steps.forEach((s,i)=>s.classList.toggle('on',i<=current));back.hidden=current===0;next.hidden=current===pages.length-1;submit.hidden=current!==pages.length-1;let partner=document.getElementById('type').value==='partner';document.getElementById('partner-help').hidden=!partner;document.getElementById('direct-help').hidden=partner;document.querySelectorAll('#clients input').forEach(x=>x.required=partner)}
next.onclick=()=>{let fields=[...pages[current].querySelectorAll('[required]')];if(fields.some(x=>!x.reportValidity()))return;current++;render()};back.onclick=()=>{current--;render()};document.getElementById('type').onchange=render;render();
</script>@endif</body></html>
